using System.IO.Compression;
using System.IO.MemoryMappedFiles;
using System.IO.Pipes;
using System.Security.Cryptography;
using System.Text;
using SharpHide.Vendor;

namespace ILTestLand;

[Virtualize]
[ControlFlow(MinBlocks = 2, MinSize = 4, MaxSize = 1800, BogusStates = 6, OpaqueDepth = 3,
    DecryptHashChance = 0.65)]
internal static class AdvancedIoCases {
    public static bool Case0751() { var path = NewPath("751.txt"); try { File.WriteAllText(path, "case-751", Encoding.UTF8); return File.ReadAllText(path, Encoding.UTF8) == "case-751"; } finally { File.Delete(path); } }
    public static bool Case0752() { var path = NewPath("752.txt"); try { File.WriteAllLines(path, new[] { "7", "5", "2" }); return File.ReadAllLines(path).SequenceEqual(new[] { "7", "5", "2" }); } finally { File.Delete(path); } }
    public static bool Case0753() { var path = NewPath("753.bin"); var expected = new byte[] { 7, 5, 3, 255 }; try { File.WriteAllBytes(path, expected); return File.ReadAllBytes(path).SequenceEqual(expected); } finally { File.Delete(path); } }
    public static bool Case0754() { var path = NewPath("754.txt"); try { File.WriteAllText(path, "75"); File.AppendAllText(path, "4"); return File.ReadAllText(path) == "754"; } finally { File.Delete(path); } }
    public static bool Case0755() { var source = NewPath("755-source.txt"); var target = NewPath("755-target.txt"); try { File.WriteAllText(source, "755"); File.Copy(source, target); return File.ReadAllText(target) == "755" && File.Exists(source); } finally { File.Delete(source); File.Delete(target); } }
    public static bool Case0756() { var source = NewPath("756-source.txt"); var target = NewPath("756-target.txt"); try { File.WriteAllText(source, "756"); File.Move(source, target); return !File.Exists(source) && File.ReadAllText(target) == "756"; } finally { File.Delete(source); File.Delete(target); } }
    public static bool Case0757() { var path = NewPath("757.txt"); try { File.WriteAllText(path, new string('x', 757)); var info = new FileInfo(path); return info.Exists && info.Length == 757 && info.Extension == ".txt"; } finally { File.Delete(path); } }
    public static bool Case0758() { var directory = NewPath("758-dir"); try { Directory.CreateDirectory(directory); File.WriteAllText(Path.Combine(directory, "a.txt"), "a"); File.WriteAllText(Path.Combine(directory, "b.txt"), "b"); return Directory.EnumerateFiles(directory).Count() == 2; } finally { if (Directory.Exists(directory)) Directory.Delete(directory, true); } }
    public static bool Case0759() { var directory = NewPath("759-dir"); try { Directory.CreateDirectory(Path.Combine(directory, "a", "b")); File.WriteAllText(Path.Combine(directory, "a", "b", "759.txt"), "759"); return Directory.GetFiles(directory, "*.txt", SearchOption.AllDirectories).Length == 1; } finally { if (Directory.Exists(directory)) Directory.Delete(directory, true); } }
    public static bool Case0760() { var path = Path.GetTempFileName(); File.WriteAllText(path, "760"); File.Delete(path); return !File.Exists(path); }
    public static bool Case0761() { var path = NewPath("761.txt"); try { File.WriteAllText(path, "761"); var timestamp = new DateTime(2026, 9, 8, 12, 0, 0, DateTimeKind.Utc); File.SetLastWriteTimeUtc(path, timestamp); return File.GetLastWriteTimeUtc(path) == timestamp; } finally { File.Delete(path); } }
    public static bool Case0762() { var path = NewPath("762.txt"); try { File.WriteAllText(path, "762"); File.SetAttributes(path, FileAttributes.ReadOnly); return File.GetAttributes(path).HasFlag(FileAttributes.ReadOnly); } finally { if (File.Exists(path)) { File.SetAttributes(path, FileAttributes.Normal); File.Delete(path); } } }
    public static bool Case0763() { using var stream = new MemoryStream("abcdef763"u8.ToArray()); stream.Seek(-3, SeekOrigin.End); return stream.ReadByte() == (byte)'7' && stream.Position == 7; }
    public static bool Case0764() { var path = NewPath("764.txt"); try { File.WriteAllTextAsync(path, "async-764").GetAwaiter().GetResult(); return File.ReadAllTextAsync(path).GetAwaiter().GetResult() == "async-764"; } finally { File.Delete(path); } }
    public static bool Case0765() { using var reader = new StreamReader(new MemoryStream("line1\n765"u8.ToArray()), Encoding.UTF8); return reader.ReadLine() == "line1" && reader.ReadLine() == "765" && reader.ReadLine() is null; }
    public static bool Case0766() { using var stream = new MemoryStream(); using (var writer = new StreamWriter(stream, Encoding.UTF8, 1024, true)) { writer.Write("case-"); writer.Write(766); } return Encoding.UTF8.GetString(stream.ToArray()).TrimStart('\ufeff') == "case-766"; }
    public static bool Case0767() { using var stream = new MemoryStream(); using (var writer = new BinaryWriter(stream, Encoding.UTF8, true)) { writer.Write(767); writer.Write("binary"); } stream.Position = 0; using var reader = new BinaryReader(stream, Encoding.UTF8, true); return reader.ReadInt32() == 767 && reader.ReadString() == "binary"; }
    public static bool Case0768() { using var target = new MemoryStream(); using (var buffered = new BufferedStream(target, 16)) { buffered.Write("768"u8); buffered.Flush(); } return target.ToArray().SequenceEqual("768"u8.ToArray()); }
    public static bool Case0769() { var key = SHA256.HashData("key-769"u8); var iv = new byte[16]; using var aes = Aes.Create(); aes.Key = key; aes.IV = iv; using var encrypted = new MemoryStream(); using (var crypto = new CryptoStream(encrypted, aes.CreateEncryptor(), CryptoStreamMode.Write, true)) crypto.Write("crypto-769"u8); encrypted.Position = 0; using var decrypt = new CryptoStream(encrypted, aes.CreateDecryptor(), CryptoStreamMode.Read); using var output = new MemoryStream(); decrypt.CopyTo(output); return output.ToArray().SequenceEqual("crypto-769"u8.ToArray()); }
    public static bool Case0770() { var input = Encoding.UTF8.GetBytes(new string('g', 770)); using var packed = new MemoryStream(); using (var gzip = new GZipStream(packed, CompressionLevel.SmallestSize, true)) gzip.Write(input); packed.Position = 0; using var gzipRead = new GZipStream(packed, CompressionMode.Decompress); using var output = new MemoryStream(); gzipRead.CopyTo(output); return output.ToArray().SequenceEqual(input) && packed.Length < input.Length; }
    public static bool Case0771() { var input = Encoding.UTF8.GetBytes(string.Concat(Enumerable.Repeat("deflate-", 771))); using var packed = new MemoryStream(); using (var compressor = new DeflateStream(packed, CompressionLevel.Optimal, true)) compressor.Write(input); packed.Position = 0; using var decompressor = new DeflateStream(packed, CompressionMode.Decompress); using var output = new MemoryStream(); decompressor.CopyTo(output); return output.ToArray().SequenceEqual(input); }
    public static bool Case0772() { var input = Encoding.UTF8.GetBytes(new string('b', 772)); using var packed = new MemoryStream(); using (var compressor = new BrotliStream(packed, CompressionLevel.Fastest, true)) compressor.Write(input); packed.Position = 0; using var decompressor = new BrotliStream(packed, CompressionMode.Decompress); using var output = new MemoryStream(); decompressor.CopyTo(output); return output.ToArray().SequenceEqual(input); }
    public static bool Case0773() { using var stream = new MemoryStream(); using (var archive = new ZipArchive(stream, ZipArchiveMode.Create, true)) { var entry = archive.CreateEntry("case.txt"); using var writer = new StreamWriter(entry.Open()); writer.Write("773"); } stream.Position = 0; using var read = new ZipArchive(stream, ZipArchiveMode.Read); using var reader = new StreamReader(read.GetEntry("case.txt")!.Open()); return reader.ReadToEnd() == "773"; }
    public static bool Case0774() { using var stream = new MemoryStream(); using (var archive = new ZipArchive(stream, ZipArchiveMode.Create, true)) for (var i = 0; i < 4; i++) { var entry = archive.CreateEntry($"{i}.txt"); using var writer = new StreamWriter(entry.Open()); writer.Write(i); } stream.Position = 0; using var read = new ZipArchive(stream, ZipArchiveMode.Read); return read.Entries.Count == 4 && read.Entries.Sum(entry => entry.Length) == 4; }
    public static bool Case0775() { var path = NewPath("775.map"); try { using (var file = new FileStream(path, FileMode.Create, FileAccess.ReadWrite, FileShare.None)) file.SetLength(1024); using var map = MemoryMappedFile.CreateFromFile(path, FileMode.Open); using (var accessor = map.CreateViewAccessor()) accessor.Write(775, (byte)75); using var check = map.CreateViewAccessor(); return check.ReadByte(775) == 75; } finally { File.Delete(path); } }
    public static bool Case0776() { using var server = new AnonymousPipeServerStream(PipeDirection.Out, HandleInheritability.None); using var client = new AnonymousPipeClientStream(PipeDirection.In, server.GetClientHandleAsString()); server.WriteByte(76); server.Flush(); return client.ReadByte() == 76; }
    public static bool Case0777() { using var server = new AnonymousPipeServerStream(PipeDirection.In, HandleInheritability.None); using var client = new AnonymousPipeClientStream(PipeDirection.Out, server.GetClientHandleAsString()); client.Write("777"u8); client.Flush(); Span<byte> data = stackalloc byte[3]; server.ReadExactly(data); return data.SequenceEqual("777"u8); }
    public static bool Case0778() { var name = "sharphide-778-" + Guid.NewGuid().ToString("N"); using var server = new NamedPipeServerStream(name, PipeDirection.InOut); using var client = new NamedPipeClientStream(".", name, PipeDirection.InOut); var read = Task.Run(() => { server.WaitForConnection(); return server.ReadByte(); }); client.Connect(2000); client.WriteByte(78); client.Flush(); return read.Wait(2000) && read.Result == 78; }
    public static bool Case0779() { using var reader = new StringReader("7\n7\n9"); return reader.ReadLine() == "7" && reader.ReadLine() == "7" && reader.ReadLine() == "9"; }
    public static bool Case0780() { using var writer = new StringWriter(); writer.Write("78"); writer.Write(0); return writer.ToString() == "780"; }
    public static bool Case0781() { using TextReader reader = new StringReader("async-781"); return reader.ReadToEndAsync().GetAwaiter().GetResult() == "async-781"; }
    public static bool Case0782() { using var writer = new StringWriter(); writer.WriteLineAsync("782").GetAwaiter().GetResult(); return writer.ToString() == "782" + Environment.NewLine; }
    public static bool Case0783() { using var source = new MemoryStream("copy-783"u8.ToArray()); using var target = new MemoryStream(); source.CopyTo(target, 3); return target.ToArray().SequenceEqual("copy-783"u8.ToArray()); }
    public static bool Case0784() { using var stream = new MemoryStream("read-784"u8.ToArray()); var buffer = new byte[8]; stream.ReadExactly(buffer); return buffer.SequenceEqual("read-784"u8.ToArray()); }
    public static bool Case0785() { using var stream = new MemoryStream("785-extra"u8.ToArray()); Span<byte> buffer = stackalloc byte[16]; var count = stream.ReadAtLeast(buffer, 3, false); return count == 9 && buffer[..count].SequenceEqual("785-extra"u8); }
    public static bool Case0786() { var path = NewPath("786.bin"); try { File.WriteAllBytes(path, new byte[16]); using var handle = File.OpenHandle(path, FileMode.Open, FileAccess.ReadWrite); RandomAccess.Write(handle, "786"u8, 4); Span<byte> buffer = stackalloc byte[3]; RandomAccess.Read(handle, buffer, 4); return buffer.SequenceEqual("786"u8); } finally { File.Delete(path); } }
    public static bool Case0787() { var path = NewPath("787.bin"); try { File.WriteAllBytes(path, Enumerable.Range(0, 16).Select(value => (byte)value).ToArray()); using var handle = File.OpenHandle(path, FileMode.Open, FileAccess.Read); var buffers = new Memory<byte>[] { new byte[4], new byte[4] }; var read = RandomAccess.Read(handle, buffers, 4); return read == 8 && buffers.SelectMany(memory => memory.ToArray()).SequenceEqual(Enumerable.Range(4, 8).Select(value => (byte)value)); } finally { File.Delete(path); } }
    public static bool Case0788() { var directory = NewPath("788-dir"); try { var info = Directory.CreateDirectory(directory); info.CreateSubdirectory("child"); return info.Exists && info.GetDirectories().Single().Name == "child"; } finally { if (Directory.Exists(directory)) Directory.Delete(directory, true); } }
    public static bool Case0789() { var directory = NewPath("789-dir"); try { Directory.CreateDirectory(directory); File.WriteAllText(Path.Combine(directory, "a.log"), "a"); File.WriteAllText(Path.Combine(directory, "b.txt"), "b"); return Directory.EnumerateFiles(directory, "*.log").Single().EndsWith("a.log", StringComparison.Ordinal); } finally { if (Directory.Exists(directory)) Directory.Delete(directory, true); } }
    public static bool Case0790() { var root = Path.Combine(Path.GetTempPath(), "case790"); var child = Path.Combine(root, "a", "b.txt"); return Path.GetRelativePath(root, child) == Path.Combine("a", "b.txt"); }
    public static bool Case0791() { return Path.ChangeExtension(Path.Combine("folder", "case.tmp"), ".791") == Path.Combine("folder", "case.791"); }
    public static bool Case0792() { var path = Path.Combine("root", "child", "792.txt"); return path.Split(Path.DirectorySeparatorChar).Last() == "792.txt"; }
    public static bool Case0793() { var basePath = Path.GetFullPath(Path.Combine(Path.GetTempPath(), "case793")); var full = Path.GetFullPath(Path.Combine("child", "..", "file.txt"), basePath); return full == Path.Combine(basePath, "file.txt"); }
    public static bool Case0794() { var root = Path.GetFullPath(Path.Combine(Path.GetTempPath(), "case794")); var child = Path.Combine(root, "nested", "file.txt"); return Path.GetRelativePath(root, child) == Path.Combine("nested", "file.txt"); }
    public static bool Case0795() { var path = Path.EndsInDirectorySeparator("folder" + Path.DirectorySeparatorChar); return path && !Path.EndsInDirectorySeparator("folder"); }
    public static bool Case0796() { var path = Path.TrimEndingDirectorySeparator("folder" + Path.DirectorySeparatorChar); return path == "folder"; }
    public static bool Case0797() { return Path.HasExtension("archive.tar.gz") && Path.GetExtension("archive.tar.gz") == ".gz"; }
    public static bool Case0798() { return Path.GetFileNameWithoutExtension(Path.Combine("folder", "case.798.txt")) == "case.798"; }
    public static bool Case0799() { var root = Path.GetPathRoot(Path.GetFullPath(Path.GetTempPath())); return !string.IsNullOrEmpty(root) && Path.IsPathFullyQualified(root); }
    public static bool Case0800() { var random = Path.GetRandomFileName(); return random.Length == 12 && random[8] == '.' && random.IndexOfAny(Path.GetInvalidFileNameChars()) < 0; }

    private static string NewPath(string suffix) => Path.Combine(Path.GetTempPath(), "sharphide-" + Guid.NewGuid().ToString("N") + "-" + suffix);
}
